const upsertReferralSettings = `-- name: UpsertReferralSettings :one
INSERT INTO referral_settings (id, commission_percentage, buyer_discount_percentage, min_payout_amount, is_enabled, terms_and_conditions, updated_at)
VALUES (1, $1, $2, $3, $4, $5, NOW())
ON CONFLICT (id) DO UPDATE
SET commission_percentage = EXCLUDED.commission_percentage,
    buyer_discount_percentage = EXCLUDED.buyer_discount_percentage,
    min_payout_amount = EXCLUDED.min_payout_amount,
    is_enabled = EXCLUDED.is_enabled,
    terms_and_conditions = EXCLUDED.terms_and_conditions,
    updated_at = NOW()
RETURNING id, commission_percentage, buyer_discount_percentage, min_payout_amount, is_enabled, terms_and_conditions, updated_at
`

type UpsertReferralSettingsParams struct {
	CommissionPercentage    string `json:"commission_percentage"`
	BuyerDiscountPercentage string `json:"buyer_discount_percentage"`
	MinPayoutAmount         string `json:"min_payout_amount"`
	IsEnabled               bool   `json:"is_enabled"`
	TermsAndConditions      string `json:"terms_and_conditions"`
}

func (q *Queries) UpsertReferralSettings(ctx context.Context, arg UpsertReferralSettingsParams) (ReferralSetting, error) {
	row := q.db.QueryRowContext(ctx, upsertReferralSettings,
		arg.CommissionPercentage,
		arg.BuyerDiscountPercentage,
		arg.MinPayoutAmount,
		arg.IsEnabled,
		arg.TermsAndConditions,
	)
	var i ReferralSetting
	err := row.Scan(
		&i.ID,
		&i.CommissionPercentage,
		&i.BuyerDiscountPercentage,
		&i.MinPayoutAmount,
		&i.IsEnabled,
		&i.TermsAndConditions,
		&i.UpdatedAt,
	)
	return i, err
}
